import pytest

from balance import BalanceError, balance, format_equation, parse_formula


def test_propane_combustion():
    eq = "C3H8 + O2 -> CO2 + H2O"
    assert balance(eq) == [1, 5, 3, 4]


def test_iron_oxide():
    coeffs = balance("Fe + O2 -> Fe2O3")
    assert coeffs == [4, 3, 2]


def test_potassium_permanganate_with_hcl():
    eq = "KMnO4 + HCl -> KCl + MnCl2 + H2O + Cl2"
    assert balance(eq) == [2, 16, 2, 2, 8, 5]


def test_aluminium_sulfate_with_calcium_hydroxide():
    eq = "Al2(SO4)3 + Ca(OH)2 -> Al(OH)3 + CaSO4"
    assert balance(eq) == [1, 3, 2, 3]


def test_impossible_equation_raises():
    with pytest.raises(BalanceError, match="balance"):
        balance("H2O -> H2O2")


def test_formatted_output_propane():
    eq = "C3H8 + O2 -> CO2 + H2O"
    assert format_equation(eq, balance(eq)) == "C3H8 + 5 O2 -> 3 CO2 + 4 H2O"


def test_parse_nested_parentheses():
    assert parse_formula("Al2(SO4)3") == {"Al": 2, "S": 3, "O": 12}
    assert parse_formula("Ca(OH)2") == {"Ca": 1, "O": 2, "H": 2}
    assert parse_formula("Mg(NO3)(OH)") == {"Mg": 1, "N": 1, "O": 4, "H": 1}
    assert parse_formula("K4(ON(SO3)2)2") == {
        "K": 4, "O": 14, "N": 2, "S": 4,
    }  # hypothetical deeply-nested case


def test_nullspace_vector_is_exact_rational():
    from fractions import Fraction

    from balance import nullspace_vector

    vec = nullspace_vector([[Fraction(1), Fraction(-2)]])
    assert vec == [Fraction(2), Fraction(1)]

